    if (b == 0) throw std::invalid_argument("denominator cannot be zero");
    return a / b;
}
int main() {
    try {
        std::cout << divide(10, 2) << '\n';
        std::cout << divide(10, 0) << '\n';
    } catch (const std::invalid_argument& e) {
        std::cerr << "Error: " << e.what() << '\n';
    }
}
~~~
Compile with g++ -std=c++11 example.cpp -o example. Catch by const reference to avoid copying; use exceptions for failures that should interrupt normal control flow.

~~~go
package main

import "fmt"

func Unique[T comparable](values []T) []T {
    seen := make(map[T]struct{}, len(values))
    result := make([]T, 0, len(values))
    for _, value := range values {
        if _, exists := seen[value]; exists { continue }
        seen[value] = struct{}{}
        result = append(result, value)
    }
    return result
}
func main() {
    fmt.Println(Unique([]int{3,1,3,2,1})) // [3 1 2]
}
~~~
This preserves the first occurrence and requires Go 1.18+ for generics. Save as main.go and run go run main.go. Expected time and extra space are O(n). For older Go, specialize the function to a concrete type such as int.

This uses JavaScript Map insertion order for recency: the first key is least recently used.
~~~javascript
class LRUCache {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 0) throw new RangeError('invalid capacity');
    this.capacity=capacity; this.values=new Map();
  }
  get(key) {
    if (!this.values.has(key)) return -1;
    const value=this.values.get(key);
    this.values.delete(key); this.values.set(key,value);
    return value;
  }
  put(key,value) {
    if (this.capacity===0) return;
    if (this.values.has(key)) this.values.delete(key);
    else if (this.values.size===this.capacity)
      this.values.delete(this.values.keys().next().value);
    this.values.set(key,value);
  }
}
const cache=new LRUCache(2);
cache.put('a',1); cache.put('b',2);
console.log(cache.get('a')); // 1, now most recent
cache.put('c',3); // evicts b
console.log(cache.get('b')); // -1
~~~
Both operations are O(1) average. Missing keys return −1; choose another sentinel if −1 could be a legitimate cached value.

~~~javascript
function permutations(text) {
  const result=[];
  function build(prefix, remaining) {
    if (remaining.length===0) { result.push(prefix); return; }
    const used=new Set();
    for (let i=0;i<remaining.length;i++) {
      const ch=remaining[i];
      if (used.has(ch)) continue;
      used.add(ch);
      build(prefix+ch, remaining.slice(0,i)+remaining.slice(i+1));
    }
  }
  build('',text);
  return result;
}
console.log(permutations('cat'));
console.log(permutations('aab')); // ['aab','aba','baa']
~~~
The set prevents duplicate permutations when characters repeat. The empty string returns [''], the one empty arrangement. Output grows factorially, so use this for relatively short strings.

~~~java
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class RemoveDuplicates {
    public static int[] uniqueInOrder(int[] values) {
        Set<Integer> seen = new HashSet<>();
        List<Integer> result = new ArrayList<>();
        for (int value : values) {
            if (seen.add(value)) result.add(value);
        }
        int[] answer = new int[result.size()];
        for (int i=0; i<answer.length; i++) answer[i]=result.get(i);
        return answer;
    }
    public static void main(String[] args) {
        int[] out=uniqueInOrder(new int[]{3,1,3,2,1});
        for (int n:out) System.out.print(n+" "); // 3 1 2
    }
}
~~~
Save as RemoveDuplicates.java, compile with javac RemoveDuplicates.java, and run java RemoveDuplicates. A set remembers seen values while the result list preserves encounter order. Expected time and additional space are O(n).

~~~cpp
#include <cctype>
#include <string>

bool isPalindromeIgnoringSpacesAndCase(const std::string& text) {
    std::size_t left=0, right=text.size();
    while (left<right) {
        while (left<right && std::isspace(static_cast<unsigned char>(text[left]))) ++left;
        while (left<right && std::isspace(static_cast<unsigned char>(text[right-1]))) --right;
        if (left>=right) break;
        unsigned char a=static_cast<unsigned char>(text[left]);
        unsigned char b=static_cast<unsigned char>(text[right-1]);
        if (std::tolower(a)!=std::tolower(b)) return false;
        ++left; --right;
    }
    return true;
}
~~~
For example, isPalindromeIgnoringSpacesAndCase("Never odd or even") returns true. Empty and all-space strings are treated as palindromes. This ignores whitespace and case only, not punctuation. The unsigned-char casts make calls to the character-classification functions well-defined. Unicode case folding requires a Unicode library.

~~~cpp
bool isPrime(int n) {
    if (n < 2) return false;
    if (n % 2 == 0) return n == 2;
    for (int d=3; d <= n/d; d += 2) {
        if (n % d == 0) return false;
    }
    return true;
}
~~~
For example, isPrime(29) returns true and isPrime(21) returns false. Testing divisors only through the square root is sufficient: a composite number must have at least one factor no larger than that. The n/d condition avoids overflow from d*d. Worst-case time is O(√n).

