}
```

Compile with a C++11-or-later compiler, for example `g++ -std=c++17 email.cpp -o email`. This is a practical check for common ASCII addresses, not a complete implementation of every allowed email syntax. A regex also cannot verify that the mailbox exists; use a confirmation email when deliverability matters.

Here is a Go implementation using an adjacency list. It returns a shortest path in an unweighted graph, or `nil` when no path exists.

```go
package main

import "fmt"

func shortestPath(graph map[string][]string, start, goal string) []string {
    queue := []string{start}
    visited := map[string]bool{start: true}
    parent := map[string]string{}

    for head := 0; head < len(queue); head++ {
        current := queue[head]
        if current == goal {
            path := []string{goal}
            for path[len(path)-1] != start {
                path = append(path, parent[path[len(path)-1]])
            }
            for i, j := 0, len(path)-1; i < j; i, j = i+1, j-1 {
                path[i], path[j] = path[j], path[i]
            }
            return path
        }
        for _, next := range graph[current] {
            if !visited[next] {
                visited[next] = true
                parent[next] = current
                queue = append(queue, next)
            }
        }
    }
    return nil
}

func main() {
    graph := map[string][]string{
        "A": {"B", "C"}, "B": {"A", "D"},
        "C": {"A", "D"}, "D": {"B", "C", "E"}, "E": {"D"},
    }
    fmt.Println(shortestPath(graph, "A", "E")) // [A B D E] or [A C D E]
}
```

Save as `main.go` and run `go run main.go`. BFS explores vertices in increasing distance from the start, so the first discovered route to the goal has the fewest edges. Its complexity is O(V + E) for a graph with V vertices and E edges.

```go
package main

import (
    "errors"
    "fmt"
)

type Stack[T any] struct {
    items []T
}

func (s *Stack[T]) Push(value T) {
    s.items = append(s.items, value)
}

func (s *Stack[T]) Pop() (T, error) {
    var zero T
    if len(s.items) == 0 {
        return zero, errors.New("pop from empty stack")
    }
    last := len(s.items) - 1
    value := s.items[last]
    s.items = s.items[:last]
    return value, nil
}

func (s *Stack[T]) Peek() (T, error) {
    var zero T
    if len(s.items) == 0 {
        return zero, errors.New("peek at empty stack")
    }
    return s.items[len(s.items)-1], nil
}

func main() {
    var stack Stack[int]
    stack.Push(10)
    stack.Push(20)
    top, _ := stack.Peek()
    fmt.Println("top:", top) // 20
    value, _ := stack.Pop()
    fmt.Println("popped:", value) // 20
}
```

This generic implementation requires Go 1.18 or newer. `Push` adds at the top, while `Pop` removes and returns the top item. Both `Pop` and `Peek` report an error for an empty stack.

```javascript
function bracketsBalanced(text) {
  const pairs = { ")": "(", "]": "[", "}": "{" };
  const opening = new Set(["(", "[", "{"]);
  const stack = [];

  for (const char of text) {
    if (opening.has(char)) {
      stack.push(char);
    } else if (Object.hasOwn(pairs, char)) {
      if (stack.length === 0 || stack.pop() !== pairs[char]) return false;
    }
  }
  return stack.length === 0;
}

console.log(bracketsBalanced("([]{})")); // true
console.log(bracketsBalanced("([)]"));   // false
```

The stack checks both matching types and nesting order. Other characters are ignored. `Object.hasOwn` is available in modern JavaScript; on older runtimes, use `Object.prototype.hasOwnProperty.call(pairs, char)`.

```javascript
function firstNonRepeatingChar(text) {
  const counts = new Map();
  for (const char of text) {
    counts.set(char, (counts.get(char) ?? 0) + 1);
  }
  for (const char of text) {
    if (counts.get(char) === 1) return char;
  }
  return null;
}

console.log(firstNonRepeatingChar("swiss")); // "w"
console.log(firstNonRepeatingChar("aabb"));  // null
```

The first pass counts each Unicode code point, and the second returns the earliest one with a count of 1. It runs in O(n) time and uses O(k) space for k distinct characters. It returns `null` if every character repeats.

```javascript
// Usage: node average-column.js data.csv amount
// Supports ordinary CSV fields, quoted fields, and escaped double quotes.
const fs = require("node:fs");

function parseCSVLine(line) {
  const fields = [];
  let field = "";
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (inQuotes) {
      if (ch === '"' && line[i + 1] === '"') {
        field += '"';
        i++;
      } else if (ch === '"') {
        inQuotes = false;
      } else {
        field += ch;
      }
    } else if (ch === '"') {
      inQuotes = true;
    } else if (ch === ",") {
      fields.push(field);
      field = "";
    } else {
      field += ch;
    }
  }
  if (inQuotes) throw new Error("Unclosed quoted field");
  fields.push(field);
  return fields;
}

const [file, columnName] = process.argv.slice(2);
if (!file || !columnName) {
  console.error("Usage: node average-column.js <file.csv> <column-name>");
  process.exit(1);
}
const lines = fs.readFileSync(file, "utf8").split(/\r?\n/).filter(Boolean);
if (lines.length < 2) throw new Error("CSV must include a header and data rows");
const headers = parseCSVLine(lines[0]);
const column = headers.indexOf(columnName);
if (column === -1) throw new Error(`Column not found: ${columnName}`);
let sum = 0;
let count = 0;
for (const line of lines.slice(1)) {
  const fields = parseCSVLine(line);
  const value = Number(fields[column]);
  if (fields[column] !== "" && Number.isFinite(value)) {
    sum += value;
    count++;
  }
}
if (count === 0) throw new Error("Column contains no numeric values");
console.log(sum / count);
```

Save this as `average-column.js` and run `node average-column.js data.csv amount`. It prints the arithmetic mean of non-empty numeric values in the named column; nonnumeric cells are skipped. This line-oriented parser supports quoted commas but not quoted fields containing embedded newlines. For arbitrary CSV files, use a dedicated CSV package such as `csv-parse`.

```go
package main

import "fmt"

func main() {
    for n := 1; n <= 100; n++ {
        switch {
        case n%15 == 0:
            fmt.Println("FizzBuzz")
        case n%3 == 0:
            fmt.Println("Fizz")
        case n%5 == 0:
