```java
import java.util.HashMap;
import java.util.Map;

/** A simple least-recently-used cache with O(1) get and put operations. */
public class LRUCache<K, V> {
    private final int capacity;
    private final Map<K, Node<K, V>> map = new HashMap<>();
    private final Node<K, V> head = new Node<>(null, null); // most recent side
    private final Node<K, V> tail = new Node<>(null, null); // least recent side

    private static final class Node<K, V> {
        K key; V value; Node<K, V> prev, next;
        Node(K key, V value) { this.key = key; this.value = value; }
    }

    public LRUCache(int capacity) {
        if (capacity < 0) throw new IllegalArgumentException("capacity must be nonnegative");
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }

    /** Returns the value, or null if the key is absent; a hit becomes most recent. */
    public V get(K key) {
        Node<K, V> node = map.get(key);
        if (node == null) return null;
        moveToFront(node);
        return node.value;
    }

    /** Inserts or updates a value, evicting the least-recently-used key if needed. */
    public void put(K key, V value) {
        if (capacity == 0) return;
        Node<K, V> node = map.get(key);
        if (node != null) {
            node.value = value;
            moveToFront(node);
            return;
        }
        node = new Node<>(key, value);
        map.put(key, node);
        addAfterHead(node);
        if (map.size() > capacity) {
            Node<K, V> lru = tail.prev;
            unlink(lru);
            map.remove(lru.key);
        }
    }

    private void moveToFront(Node<K, V> node) {
        unlink(node);
        addAfterHead(node);
    }
    private void addAfterHead(Node<K, V> node) {
        node.prev = head;
        node.next = head.next;
        head.next.prev = node;
        head.next = node;
    }
    private void unlink(Node<K, V> node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    public static void main(String[] args) {
        LRUCache<Integer, String> cache = new LRUCache<>(2);
        cache.put(1, "one");
        cache.put(2, "two");
        System.out.println(cache.get(1)); // one; key 1 is now most recent
        cache.put(3, "three");         // evicts key 2
        System.out.println(cache.get(2)); // null
    }
}
```

The hash map finds entries in expected \(O(1)\) time; the doubly linked list tracks recency so moving or evicting an entry is also \(O(1)\). Here `null` means a cache miss, so if null values must be supported unambiguously, use a separate result type or a `containsKey` check.

~~~go
func rotateClockwise(m [][]int) [][]int {
 n:=len(m); out:=make([][]int,n)
 for r:=range m { if len(m[r])!=n { panic("matrix must be square") }; out[r]=make([]int,n) }
 for r:=0;r<n;r++ { for c:=0;c<n;c++ { out[c][n-1-r]=m[r][c] } }
 return out
}
