def roman_to_int(s: str) -> int:
    values = {"I":1,"V":5,"X":10,"L":50,"C":100,"D":500,"M":1000}
    s=s.strip().upper()
    if not s: raise ValueError("Roman numeral cannot be empty")
    total=0
