~~~java
import java.util.*;
public class BFSShortestPath {
 static List<Integer> shortestPath(Map<Integer,List<Integer>> g,int start,int target) {
  Queue<Integer> q=new ArrayDeque<>();
  Map<Integer,Integer> parent=new HashMap<>();
  Set<Integer> seen=new HashSet<>();
  q.add(start); seen.add(start);
  while(!q.isEmpty()) {
   int u=q.remove();
   if(u==target) break;
   for(int v:g.getOrDefault(u,Collections.emptyList()))
    if(seen.add(v)){parent.put(v,u);q.add(v);}
  }
  if(!seen.contains(target)) return Collections.emptyList();
  LinkedList<Integer> path=new LinkedList<>();
  for(int v=target;;v=parent.get(v)){path.addFirst(v);if(v==start)break;}
  return path;
 }
 public static void main(String[] args) {
  Map<Integer,List<Integer>> g=new HashMap<>();
  g.put(1,Arrays.asList(2,3));g.put(2,Arrays.asList(1,4));
  g.put(3,Arrays.asList(1,4));g.put(4,Arrays.asList(2,3));
  System.out.println(shortestPath(g,1,4)); // [1, 2, 4]
 }
}
~~~
BFS visits vertices in increasing edge distance, so its first discovered route to the target is shortest in an unweighted graph. Runtime and space are O(V+E).

