 auto val=[](char c) {
  switch(std::toupper(static_cast<unsigned char>(c))) {
   case 'I':return 1; case 'V':return 5; case 'X':return 10;
   case 'L':return 50; case 'C':return 100; case 'D':return 500;
   case 'M':return 1000; default:return 0;
  }
 };
 int total=0;
 for(std::size_t i=0;i<s.size();++i) {
  int cur=val(s[i]); if(!cur) throw std::invalid_argument("invalid numeral");
  int next=i+1<s.size()?val(s[i+1]):0;
  if(i+1<s.size()&&!next) throw std::invalid_argument("invalid numeral");
  total += cur<next ? -cur : cur;
 }
 return total;
}
