// Fibonacci returns F(n), with F(0)=0 and F(1)=1.
func Fibonacci(n int) (uint64,error) {
 if n<0 { return 0,fmt.Errorf("n must be nonnegative") }
 if n<2 { return uint64(n),nil }
 var prev,cur uint64=0,1
 for i:=2;i<=n;i++ { prev,cur=cur,prev+cur }
 return cur,nil
}
